] : phase==='aggregate' ? [
  ['adp01-full-suite-final','node_modules/vitest/vitest.mjs','run','--maxWorkers=1','--no-file-parallelism'],
] : null;
if(!jobs)throw new Error('Choose preflight or aggregate');
if(phase==='preflight-v2')jobs=jobs.map(([name,...args])=>[name+'-v2',...args]);
for(const args of jobs){
  if(existsSync(`C:/Users/sboad/.codex/tmp/health-n2-20261001/${args[0]}-start.json`))throw new Error('Do not overwrite '+args[0]);
  const result=spawnSync(process.execPath,[wrapper,...args],{cwd:'C:/Users/sboad/.codex/worktrees/b22f/xenios-website',stdio:'inherit',windowsHide:true});
  if(result.status!==0){process.exitCode=result.status??1;break;}
}

import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';

const root = 'C:/Users/sboad/.codex/worktrees/b22f/xenios-website';
const scratch = 'C:/Users/sboad/.codex/tmp/health-n2-20261001';
const [source, tests, controls, checkpoint, fullJob] = process.argv.slice(2);
if (![source, tests, controls, checkpoint].every(v => /^[a-f0-9]{40}$/.test(v ?? '')) || !/^adp01-full-suite-[a-z0-9-]+$/.test(fullJob ?? '')) throw new Error('Four full SHAs and exact aggregate job required');
const read = file => fs.readFileSync(file, 'utf8');
const json = file => JSON.parse(read(file));
const digest = bytes => createHash('sha256').update(bytes).digest('hex');
const sha = file => digest(fs.readFileSync(file));
const git = (...args) => execFileSync('git', args, { cwd: root, encoding: 'utf8' }).trim();
const clean = value => value.replace(/\u001b\[[0-9;]*m/g, '');
const counts = value => {
  const text=clean(value), test=text.match(/^\s*Tests\s+(.+)$/m)?.[1], files=text.match(/^\s*Test Files\s+(.+)$/m)?.[1] ?? '';
  const n=(s,state)=>Number(s.match(new RegExp('(\\d+) '+state))?.[1] ?? 0);
  return test ? {passed:n(test,'passed'),failed:n(test,'failed'),skipped:n(test,'skipped'),filesPassed:n(files,'passed'),
    filesFailed:n(files,'failed'),filesSkipped:n(files,'skipped'),duration:text.match(/^\s*Duration\s+(.+)$/m)?.[1] ?? null} : null;
};
const jobs=fs.readdirSync(scratch).filter(n=>n.startsWith('adp01-')&&n.endsWith('.log')).sort().map(name=>{
  const job=name.slice(0,-4), log=path.join(scratch,name), result=path.join(scratch,`${job}-result.json`), provenance=path.join(scratch,`${job}-provenance.json`);
  const record=fs.existsSync(result)?json(result):null, snapshots=fs.existsSync(provenance)?json(provenance):null;
  if(record?.logSha256 && record.logSha256!==sha(log))throw new Error('Log drift: '+job);
  return {job,log,sha256:sha(log),counts:counts(read(log)),record,
    childRuntimeProvenance:snapshots?{path:provenance,sha256:sha(provenance),snapshots}:null,
    provenanceLimit:!record?'Subordinate log only; no independent runner command/HEAD/exit receipt. Interpret exact content, not inferred aggregate success.'
      :!snapshots?.length?'Short run has no sampled child attestation; recorded launch path is not lifetime process proof.'
      :'Sampled process snapshots only, not continuous attestation of every transient child; unavailable executable paths remain explicitly unavailable.'};
});
const full=jobs.find(j=>j.job===fullJob);
if(!full?.record||!Number.isInteger(full.record.exitCode)||!full.record.finishedAt||!full.counts)throw new Error('Completed aggregate required, never infer success');
const samePath=(left,right)=>typeof left==='string'&&typeof right==='string'&&path.resolve(left).toLowerCase()===path.resolve(right).toLowerCase();
const pinnedNode='C:/Users/sboad/.codex/tmp/node-v20.19.0-win-x64/node.exe';
const fullArgs=['node_modules/vitest/vitest.mjs','run','--maxWorkers=1','--no-file-parallelism'];
if(full.record.node!=='v20.19.0'||full.record.npm!=='10.8.2'||!samePath(full.record.execPath,pinnedNode)||
  !samePath(full.record.command?.[0],pinnedNode)||JSON.stringify(full.record.command?.slice(1))!==JSON.stringify(fullArgs)||
  !samePath(full.record.cwd,root)||!samePath(full.record.dataset,path.join(root,'server/research/master-offerings/data/member-safe-master-offerings.generated.json')))
  throw new Error('Aggregate runtime, exact command or real dataset provenance mismatch');
if(full.record.head!==checkpoint||full.record.tree!==git('rev-parse',`${checkpoint}^{tree}`)||full.record.dirtyAtStart!=='')throw new Error('Aggregate did not start at exact clean checkpoint');
const isRecord=p=>p.startsWith('.xenios/')||/^server\/research\/assisted-order\/HEALTH_HL12_ADP01_[^/]+\.(md|json)$/.test(p);
const dirtyPaths=v=>(v??'').split('\n').filter(Boolean).map(line=>line.replace(/^[ MADRCU?!]{1,2} /,'').replace(/^"|"$/g,''));
if([...dirtyPaths(full.record.dirtyAtEnd),...dirtyPaths(git('status','--short'))].some(p=>!isRecord(p)))throw new Error('Non-record working changes after freeze');
for(const revision of [full.record.finalHead,git('rev-parse','HEAD')])if(git('diff','--name-only',checkpoint,revision).split('\n').filter(Boolean).some(p=>!isRecord(p)))throw new Error('Non-record committed changes after freeze');
for(const revision of [source,tests,controls])git('merge-base','--is-ancestor',revision,checkpoint);
const base='48a598f45161cccbf39d5945b85e14a9c31b6b6a', throughHead=git('rev-parse','HEAD');
const controlPaths=['docs/coordination/MIGRATION_DAG.json','supabase/MIGRATIONS.md','server/release-control-plane.test.ts'];
const testPath=p=>p.endsWith('.test.ts')||p.startsWith('supabase/verification/research_assisted_order_quote_provider_journal');
const commits=git('rev-list','--reverse',`${base}..${throughHead}`).split('\n').filter(Boolean).map(commit=>{
  const paths=git('diff-tree','--no-commit-id','--name-only','-r',commit).split('\n').filter(Boolean);
  const kind=paths.every(isRecord)?'records_only':paths.every(p=>controlPaths.includes(p))?'release_controls':paths.every(testPath)?'test_only'
    :paths.every(p=>!isRecord(p)&&!testPath(p)&&!controlPaths.includes(p))?'runtime_source':'MIXED_REQUIRES_REVIEW';
  if(kind==='MIXED_REQUIRES_REVIEW')throw new Error('Unclassified mixed commit '+commit);
  return {sha:commit,kind,subject:git('show','-s','--format=%s',commit),paths};
});
const migration='supabase/migrations/20261001085559_research_assisted_order_quote_provider_journal.sql';
for(const [kind,expected] of [['runtime_source',source],['test_only',tests],['release_controls',controls]]){
  const latest=commits.filter(commit=>commit.kind===kind).at(-1);
  if(latest?.sha!==expected)throw new Error('Not latest classified '+kind+' tip: '+expected);
}
const dag=json(path.join(root,'docs/coordination/MIGRATION_DAG.json'));
const chain=[], visited=new Set();
function visit(id){
  if(visited.has(id))return;
  const node=dag.migrations.find(n=>n.id===id);if(!node)throw new Error('Missing migration '+id);
  for(const parent of node.dependsOn)visit(parent);
  const sourceSha=node.sourceSha??dag.productionSha, sourcePath=node.sourcePath??node.path;
  const actual=digest(execFileSync('git',['show',`${sourceSha}:${sourcePath}`],{cwd:root}));
  if(actual!==node.checksum.value)throw new Error('Prerequisite checksum drift '+id);
  visited.add(id);chain.push({id,path:node.path,sourceSha,sourcePath,sha256:actual,dependsOn:node.dependsOn,
    recordedAppliedToProduction:node.appliedToProduction,recordedManagedMigrationId:node.managedMigrationId,managedReobserved:false});
}
visit('research_assisted_order_quote_provider_journal');
const receipt={schemaVersion:1,generatedAt:new Date().toISOString(),status:'LOCAL_SOURCE_AND_TEST_EVIDENCE_NOT_RELEASE_OR_CLAUDE_ACCEPTANCE',
  aggregateStatus:full.record.exitCode===0?'PASS_LOCAL_ONLY':'FAILED_NOT_RELEASE_READY',
  aggregateFailures:clean(read(full.log)).split('\n').filter(l=>/^\s*FAIL\s/.test(l)).map(l=>l.trim()),
  branch:git('branch','--show-current'),runtimeSha:source,runtimeTree:git('rev-parse',`${source}^{tree}`),testOnlySha:tests,releaseControlSha:controls,
  qualificationCheckpoint:checkpoint,qualificationTree:git('rev-parse',`${checkpoint}^{tree}`),
  node:full.record.node,npm:full.record.npm,officialWindowsX64ArchiveSha256:'be72284c7bc62de07d5a9fd0ae196879842c085f11f7f2b60bf8864c0c9d6a4f',
  localEvidenceTooling:['run-check.mjs','run-adp01-gates.mjs','collect-adp01-qualification.mjs'].map(name=>({name,sha256:sha(path.join(scratch,name)),source:read(path.join(scratch,name))})),
  migration:{path:migration,canonicalGitBlobSha256:digest(execFileSync('git',['show',`${source}:${migration}`],{cwd:root})),rawWorktreeSha256:sha(path.join(root,migration)),managedApplied:false},
  migrationPrerequisites:{chain,limitation:'Repository source checks only. Historical managed labels are not refreshed observations. Synthetic harness role grants are not managed instructions.'},
  boundary:{productionSource:null,webhookMounted:false,providerExecutionEnabled:false,settlementEnabled:false,refundEnabled:false,historicalPaidAdoption:false,syntheticAuthOnly:true},
  classification:{base,throughHead,commits,limitation:'Ends at throughHead; this receipt and later canonical handoff are records-only successors reported after push.'},
  fullSuite:full,jobs,
  aggregateFreezeEvidence:{cleanStart:true,sourceOrTestWritesPerformedByThisSession:false,endpointAndCommittedDiffsRecordsOnly:true,continuousFilesystemAttestation:false,
    limitation:'Checks endpoints and committed differences, not an unobserved write-and-revert between observations.'},
  previousAggregate:{receipt:'server/research/master-offerings/HEALTH_HL11_QUALIFICATION_20261001.json',head:'f634e8630b92818ea494aa96f5f68c921441455b',passed:18894,failed:1,skipped:85,exitCode:1,reclassified:false},
  limitations:[
    'Independent Claude acceptance pending. Local synthetic adapter/auth stamps and psql RPC transport do not qualify actual provider authentication, managed PostgREST, hosted JWT or bank provenance.',
    'No new browser/zoom evidence. Earlier browser records belong to their exact prior candidates.',
    'All held attempts and authenticated uncertainty remain held; no settlement, external execution, refund, historical adoption or evidence-source activation is implemented by this slice.',
    'Schema seal is a drift check, not a provider fact or protection against arbitrary database-owner DDL. Managed prerequisite definitions, ACLs, RLS, default privileges and history still require qualification.',
    'Interrupted-write checks exercise rollback/response-loss boundaries, not physical DB crash recovery at every instruction.',
    'Runtime snapshots walk node.exe-only ancestry: descendants reached through cmd.exe or another non-Node intermediary can be missed. In particular build snapshots show the runner/npm CLI, not independently observed Vite/tsx children. Process-local pinned PATH is launch configuration, not continuous child attestation.',
    'Runner and collector source bytes are archived here; earlier scratch-only diagnostic reproduction scripts are not. Their recorded commands, log hashes and exit results remain evidence but are not a portable archived reproduction package.',
    'Failed, skipped, diagnostic reproductions and timed-out runs remain distinct; focused passes cannot replace the aggregate exit status.',
    'Protected seam baselines are unchanged. No old hash approval is reused.',
    'Imagery/media decoupling remain independent and unintegrated; no approved public asset inference.',
  ],managedMigrationApplied:false,hostedConfigurationChanged:false,productionMutated:false,stagingMutated:false,deployed:false,merged:false,
  priceRelease:false,accountGrantsCreated:false,realEmailSent:false,realMoneyMoved:false};
const out=path.join(root,'server/research/assisted-order/HEALTH_HL12_ADP01_QUALIFICATION_20261001.json');
fs.writeFileSync(out,JSON.stringify(receipt,null,2)+'\n');
console.log(JSON.stringify({out,fullSuite:full.counts,exitCode:full.record.exitCode,jobs:jobs.length}));
